contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry performing the property check
    function run(uint256 seedMarketDrugs) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(true);

        // seed the market to initialize the contract. seedMarket requires marketDrugs==0
        // and is payable; send no Ether (allowed) and set marketDrugs to seedMarketDrugs
        c.seedMarket{value: 0}(seedMarketDrugs); if (__ESBMC_reverted()) return;

        // ensure the caller currently has zero kilos (getMyKilo reads Kilos[msg.sender])
        // the fresh c should have Kilos[this]==0; call getMyKilo view
        uint256 kilosBefore = c.getMyKilo(); if (__ESBMC_reverted()) return;

        // record lastCollect before
        uint256 lastBefore = c.lastCollect(address(this)); if (__ESBMC_reverted()) return;

        // call getFreeKilo which should set Kilos[msg.sender] to STARTING_KILOS and lastCollect to block.timestamp
        c.getFreeKilo(); if (__ESBMC_reverted()) return;

        // observe after-values via public getters
        uint256 kilosAfter = c.getMyKilo(); if (__ESBMC_reverted()) return;
        uint256 lastAfter = c.lastCollect(address(this)); if (__ESBMC_reverted()) return;
        uint256 starting = c.STARTING_KILOS(); if (__ESBMC_reverted()) return;
        bool initialized = c.initialized(); if (__ESBMC_reverted()) return;
        uint256 nowTimestamp = block.timestamp;

        // Assert the general rule:
        // If caller had 0 kilos before and contract was initialized by seedMarket, then after getFreeKilo:
        // - caller's kilos equals STARTING_KILOS
        // - lastCollect is set to a timestamp >= lastBefore and <= current block timestamp
        // - contract remains initialized
        assert(
            kilosBefore == 0 && initialized == true
            ? (kilosAfter == starting && lastAfter >= lastBefore && lastAfter <= nowTimestamp && initialized == true)
            : true
        );
    }

    receive() external payable { }
}

