// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedMarketDrugs) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        try c.seedMarket{value: 0}(seedMarketDrugs) {} catch { return; }
        uint256 kilosBefore;
        try c.getMyKilo() returns (uint256 __r) { kilosBefore = __r; } catch { return; }
        uint256 lastBefore;
        try c.lastCollect(address(this)) returns (uint256 __r) { lastBefore = __r; } catch { return; }
        try c.getFreeKilo() {} catch { return; }
        uint256 kilosAfter;
        try c.getMyKilo() returns (uint256 __r) { kilosAfter = __r; } catch { return; }
        uint256 lastAfter;
        try c.lastCollect(address(this)) returns (uint256 __r) { lastAfter = __r; } catch { return; }
        uint256 starting;
        try c.STARTING_KILOS() returns (uint256 __r) { starting = __r; } catch { return; }
        bool initialized;
        try c.initialized() returns (bool __r) { initialized = __r; } catch { return; }
        uint256 nowTimestamp = block.timestamp;
        assertTrue(kilosBefore == 0 && initialized == true
            ? (kilosAfter == starting && lastAfter >= lastBefore && lastAfter <= nowTimestamp && initialized == true)
            : true);
    }

    function testFuzz_run(uint256 seedMarketDrugs) public {
        _run(seedMarketDrugs);
    }

    receive() external payable { }
}
